def compute(vars):
    leasehold_improvements = vars["v1"]
    total_property_equipment = vars["v2"]

    if total_property_equipment == 0:
        return None

    percentage = (leasehold_improvements / total_property_equipment) * 100

    return {
        "value": percentage,
        "trace": {
            "leasehold_improvements": leasehold_improvements,
            "total_property_equipment": total_property_equipment,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
